const statuses:Status[]=["Pendente","Em Frete","Concluído","Cancelado"];
const priorityStyle={Alta:"bg-red-50 text-red-700",Média:"bg-amber-50 text-amber-700",Baixa:"bg-slate-100 text-slate-600"};
const statusStyle:Record<Status,string>={Pendente:"bg-amber-50 text-amber-700 border-amber-200","Em Frete":"bg-blue-50 text-blue-700 border-blue-200",Concluído:"bg-emerald-50 text-emerald-700 border-emerald-200",Cancelado:"bg-red-50 text-red-700 border-red-200"};
const nowParts=()=>{const n=new Date();return{date:n.toLocaleDateString("pt-BR"),time:n.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"}),iso:n.toISOString().slice(0,10)}};
const operationKey=(value=new Date())=>{const d=new Date(value);if(d.getHours()<7)d.setDate(d.getDate()-1);return `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,"0")}${String(d.getDate()).padStart(2,"0")}`};
const operationLabel=(key:string)=>`Operação ${key.slice(6,8)}/${key.slice(4,6)}/${key.slice(0,4)}`;
const equipmentText=(f:Frete)=>[f.equipamentoTipo,f.equipamentoCodigo].filter(Boolean).join(" ").trim();
const freightText=(f:Frete)=>{const equipment=equipmentText(f);if(!equipment)return `Frete de ${f.origem} para ${f.destino}.`;const feminine=/^(Pá Carregadeira|Colhedora|Escavadeira|Motoniveladora|Plantadora)/i.test(equipment);return `Frete ${feminine?"da":"do"} ${equipment} da ${f.origem} para ${f.destino}.`};
const withObservation=(f:Frete)=>`${freightText(f)}${f.observacao.trim()?` | ${f.observacao.trim()}`:""}`;
type HistoryPeriod="Todos"|"Hoje"|"Ontem"|"Últimos 7 dias"|"Últimos 30 dias"|"Personalizado";
const ptDate=(value:string)=>{const [d,m,y]=value.split("/").map(Number);return new Date(y,m-1,d)};
const inPeriod=(value:string,period:HistoryPeriod,start:string,end:string)=>{if(period==="Todos")return true;const date=ptDate(value),today=new Date();today.setHours(0,0,0,0);if(period==="Hoje")return date.getTime()===today.getTime();if(period==="Ontem"){const yesterday=new Date(today);yesterday.setDate(yesterday.getDate()-1);return date.getTime()===yesterday.getTime()}if(period==="Personalizado"){const from=start?new Date(start+"T00:00:00"):null,to=end?new Date(end+"T23:59:59"):null;return(!from||date>=from)&&(!to||date<=to)}const days=period==="Últimos 7 dias"?7:30,from=new Date(today);from.setDate(from.getDate()-(days-1));return date>=from&&date<=today};

export function PranchasDashboard({user}:{user:AuthUser}){
 const [fretes,setFretes]=useState(initialFretes),[frotas,setFrotas]=useState(initialFrotas),[manutencoes,setManutencoes]=useState(initialManutencoes),[equipamentos,setEquipamentos]=useState(initialEquipamentos);
 useEffect(()=>{setFrotas(FROTAS_FIXAS.map(config=>{const initial=initialFrotas.find(f=>f.numero===config.numero);return {...config,status:initial?.status||"Disponível",localDisponivel:initial?.localDisponivel}}))},[]);
 const [search,setSearch]=useState(""),[filter,setFilter]=useState<Status|"Todos">("Todos"),[selected,setSelected]=useState<Frete|null>(null),[newOpen,setNewOpen]=useState(false),[equipmentOpen,setEquipmentOpen]=useState(false),[startFrete,setStartFrete]=useState<Frete|null>(null),[editFrete,setEditFrete]=useState<Frete|null>(null),[cancelFrete,setCancelFrete]=useState<Frete|null>(null),[completeFrete,setCompleteFrete]=useState<Frete|null>(null),[maintenanceOpen,setMaintenanceOpen]=useState(false),[preOsFrota,setPreOsFrota]=useState<Frota|null>(null),[flow,setFlow]=useState(""),[copied,setCopied]=useState(false),[mobile,setMobile]=useState(false),[historyTab,setHistoryTab]=useState<"fretes"|"manutencao">("fretes");
 const flowRef=useRef<HTMLDivElement>(null);
 const filtered=useMemo(()=>fretes.filter(f=>(filter==="Todos"||f.status===filter)&&[f.frota,f.motorista,f.origem,f.destino,f.setor,f.solicitante,f.equipamentoTipo,f.equipamentoCodigo].join(" ").toLowerCase().includes(search.toLowerCase())),[fretes,filter,search]);
 const updateFrete=(id:string,patch:Partial<Frete>)=>setFretes(fs=>fs.map(f=>f.id===id?{...f,...patch}:f));
 const saveEdit=(data:Partial<Frete>)=>{if(!editFrete)return;if(editFrete.status==="Concluído"){window.alert("Fretes concluídos não podem ser alterados.");setEditFrete(null);return}const normalized={...data,equipamentoId:undefined,equipamentoCodigo:undefined},n=nowParts(),fields=["equipamentoTipo","origem","destino","motorista","frota","solicitante","responsavel","setor","observacao"] as const,changes=fields.filter(k=>(editFrete[k]||"")!==(normalized[k]||"")).map(k=>({alteradoEm:`${n.date} ${n.time}`,campo:k,valorAnterior:String(editFrete[k]||""),novoValor:String(normalized[k]||"")}));if(editFrete.status==="Em Frete"&&normalized.frota&&normalized.frota!==editFrete.frota)setFrotas(fs=>fs.map(f=>f.numero===editFrete.frota?{...f,status:"Disponível"}:f.numero===normalized.frota?{...f,status:"Em Frete"}:f));updateFrete(editFrete.id,{...normalized,historicoAlteracoes:[...(editFrete.historicoAlteracoes||[]),...changes]});setEditFrete(null)};
 const confirmCancellation=(solicitadoPor:string,motivo:string)=>{if(!cancelFrete)return;if(cancelFrete.status==="Concluído"||cancelFrete.status==="Cancelado"){window.alert("Fretes concluídos não podem ser cancelados.");setCancelFrete(null);return}const n=nowParts();updateFrete(cancelFrete.id,{status:"Cancelado",cancelamentoSolicitadoPor:solicitadoPor,motivoCancelamento:motivo,canceladoEm:`${n.date} ${n.time}`});if(cancelFrete.status==="Em Frete"&&cancelFrete.frota)setFrotas(fs=>fs.map(f=>f.numero===cancelFrete.frota?{...f,status:"Disponível"}:f));setSelected(null);setCancelFrete(null)};
 const start=(frete:Frete,d:DeslocamentoInput)=>{const n=nowParts();updateFrete(frete.id,{...d,status:"Em Frete",operacao:operationKey(),inicioDeslocamento:`${n.date} ${n.time}`});setFrotas(fs=>fs.map(f=>f.numero===d.frota?{...f,status:"Em Frete"}:f));setStartFrete(null);setSelected(null)};
 const complete=(frete:Frete,local:"Aralco"|"Generalco")=>{const n=nowParts();updateFrete(frete.id,{status:"Concluído",operacao:operationKey(),conclusao:`${n.date} ${n.time}`});if(frete.frota)setFrotas(fs=>fs.map(f=>f.numero===frete.frota?{...f,status:"Disponível",localDisponivel:local}:f));setCompleteFrete(null);setSelected(null)};
 const addMaintenance=(d:ManutencaoInput)=>{const n=nowParts(),interrupted=fretes.find(f=>f.status==="Em Frete"&&f.frota===d.frota);setManutencoes(ms=>[{id:`MN-${202+ms.length}`,frota:d.frota,numeroOs:d.numeroOs,localizacao:d.localizacao,entradaData:new Date(d.entradaData+"T12:00").toLocaleDateString("pt-BR"),entradaHora:d.entradaHora,tipo:d.tipo,servico:d.servico,observacoes:d.observacoes,previsao:d.previsao==="sim",previsaoData:d.previsaoData?new Date(d.previsaoData+"T12:00").toLocaleDateString("pt-BR"):undefined,previsaoHora:d.previsaoHora,responsavel:"Ana Ribeiro",status:"Em manutenção",freteId:interrupted?.id,freteResumo:interrupted?freightText(interrupted):undefined,preOsUtilizada:d.usarPreOs==="sim"},...ms]);setFrotas(fs=>fs.map(f=>f.numero===d.frota?{...f,status:"Manutenção"}:d.transferir==="sim"&&f.numero===d.novaFrota?{...f,status:"Em Frete"}:f));if(interrupted&&d.transferir==="sim"&&d.novaFrota&&d.novoMotorista)updateFrete(interrupted.id,{frotaInicial:interrupted.frotaInicial||interrupted.frota,frotaAnterior:d.frota,frota:d.novaFrota,motorista:d.novoMotorista,motivoTransferencia:`Manutenção da frota ${d.frota}: ${d.servico}`,transferidoEm:`${n.date} ${n.time}`});setMaintenanceOpen(false)};
 const finishMaintenance=(m:Manutencao)=>{const n=nowParts();setManutencoes(ms=>ms.map(x=>x.id===m.id?{...x,status:"Finalizada",saidaData:n.date,saidaHora:n.time}:x));setFrotas(fs=>fs.map(f=>f.numero===m.frota?{...f,status:"Disponível",...(m.preOsUtilizada?{possuiPreOs:false,numeroPreOs:undefined,servicoPreOs:undefined}:{})}:f))};
 const generate=()=>{
  const pending=fretes.filter(f=>f.status==="Pendente");
  const maintenance=manutencoes.filter(m=>m.status==="Em manutenção");
  const maintenanceFleetNumbers=new Set(maintenance.map(m=>m.frota));
  const fleetSituation=FROTAS_FIXAS
   .filter(config=>!maintenanceFleetNumbers.has(config.numero))
   .map(config=>{
    const movingFreight=fretes.find(f=>f.status==="Em Frete"&&f.frota===config.numero);
    const fleet=frotas.find(f=>f.numero===config.numero);
    const preOs=fleet?.possuiPreOs?` | ⚠️ Pré-OS: ${fleet.numeroPreOs} - ${fleet.servicoPreOs}`:"";
    if(movingFreight)return `*${config.numero}* - ${withObservation(movingFreight)}${preOs}`;
    return `*${config.numero}* - Disponível${fleet?.localDisponivel?` ${fleet.localDisponivel}`:""}${preOs}`;
   });
  const orderedMaintenance=[...maintenance].sort((a,b)=>FROTAS_FIXAS.findIndex(f=>f.numero===a.frota)-FROTAS_FIXAS.findIndex(f=>f.numero===b.frota));
  setFlow(`🚛 *SITUAÇÃO DAS PRANCHAS*\n\n${fleetSituation.join("\n\n")}\n\n================================\n\n▶️ *FRETES PENDENTES*\n\n${pending.length?pending.map(f=>`* ${withObservation(f)}`).join("\n\n"):"Nenhum frete pendente."}\n\n================================\n\n🔧 *PRANCHAS EM MANUTENÇÃO*\n\n${orderedMaintenance.length?orderedMaintenance.map(m=>m.freteResumo?`*${m.frota}* - ${m.freteResumo.replace(/\.$/,"")} interrompido. Localização: ${m.localizacao}. OS: ${m.numeroOs}. ${m.servico}. ${m.previsao?`Previsão: ${m.previsaoData?.slice(0,5)} às ${m.previsaoHora}.`:"Sem previsão."}`:`*${m.frota}* - ${m.servico} | OS: ${m.numeroOs} | Local: ${m.localizacao} | ${m.previsao?`Previsão: ${m.previsaoData?.slice(0,5)} às ${m.previsaoHora}.`:"Sem previsão."}`).join("\n\n"):"Nenhuma prancha em manutenção."}`)
 };
 const copy=async()=>{await navigator.clipboard.writeText(flow);setCopied(true);setTimeout(()=>setCopied(false),1500)},download=async()=>{if(!flowRef.current)return;const data=await toPng(flowRef.current,{backgroundColor:"#fff",pixelRatio:2});const a=document.createElement("a");a.download="programacao-pranchas.png";a.href=data;a.click()},send=()=>window.open(`https://wa.me/?text=${encodeURIComponent(flow)}`,"_blank");
 return <div className="min-h-screen bg-[#f5f7f5] lg:flex"><Sidebar mobile={mobile} close={()=>setMobile(false)} user={user}/><main className="min-w-0 flex-1 lg:ml-[238px]"><MobileHeader open={()=>setMobile(true)}/><div className="mx-auto max-w-[1700px] p-4 sm:p-6 lg:p-8"><Header search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} onNew={()=>setNewOpen(true)} onEquipment={()=>setEquipmentOpen(true)} onMaintenance={()=>setMaintenanceOpen(true)}/><Indicators fretes={fretes} manutencoes={manutencoes}/><div className="mt-6 grid gap-6 xl:grid-cols-[minmax(0,1fr)_310px]"><div className="min-w-0 space-y-6"><Kanban fretes={filtered} frotas={frotas} manutencoes={manutencoes} onFrete={setSelected} onEdit={setEditFrete} onCancel={setCancelFrete} onFinishMaintenance={finishMaintenance}/><HistoryTabs tab={historyTab} setTab={setHistoryTab} fretes={filtered} onFrete={setSelected} manutencoes={manutencoes} filter={filter} setFilter={setFilter}/></div><aside className="space-y-6"><Whatsapp flow={flow} flowRef={flowRef} generate={generate} copy={copy} download={download} send={send} copied={copied}/><FleetStatus frotas={frotas} onPreOs={setPreOsFrota}/></aside></div></div></main><FreteDrawer frete={selected} close={()=>setSelected(null)} start={()=>{setStartFrete(selected);setSelected(null)}} complete={()=>{setCompleteFrete(selected);setSelected(null)}}/><FinalizeFreteModal frete={completeFrete} close={()=>setCompleteFrete(null)} confirm={complete}/><NewFrete open={newOpen} close={()=>setNewOpen(false)} equipamentos={equipamentos} add={f=>setFretes(fs=>[f,...fs])}/><EquipmentModal open={equipmentOpen} close={()=>setEquipmentOpen(false)} equipamentos={equipamentos} add={e=>setEquipamentos(es=>[e,...es])}/><StartModal frete={startFrete} close={()=>setStartFrete(null)} frotas={frotas} confirm={start}/><CancelFreteModal frete={cancelFrete} close={()=>setCancelFrete(null)} confirm={confirmCancellation}/><EditFreteModal frete={editFrete} frotas={frotas} equipamentos={equipamentos} close={()=>setEditFrete(null)} save={saveEdit}/><PreOsModal frota={preOsFrota} close={()=>setPreOsFrota(null)} save={(numero,servico)=>{setFrotas(fs=>fs.map(f=>f.numero===preOsFrota?.numero?{...f,possuiPreOs:true,numeroPreOs:numero,servicoPreOs:servico}:f));setPreOsFrota(null)}}/><MaintenanceTrackingModal open={maintenanceOpen} close={()=>setMaintenanceOpen(false)} frotas={frotas} fretes={fretes} save={addMaintenance}/></div>
}

function Brand(){return <div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#d6f269] text-[#183527]"><Truck size={19}/></div><div><div className="font-semibold text-white">Plataforma</div><div className="text-xs text-white/45">Logística integrada</div></div></div>}
function Sidebar({mobile,close,user}:{mobile:boolean;close:()=>void;user:AuthUser}){return <><div onClick={close} className={`fixed inset-0 z-30 bg-black/30 lg:hidden ${mobile?"block":"hidden"}`}/><aside className={`fixed inset-y-0 left-0 z-40 flex w-[238px] flex-col bg-[#17231d] p-5 text-white transition-transform lg:translate-x-0 ${mobile?"translate-x-0":"-translate-x-full"}`}><Brand/><nav className="mt-10 space-y-1.5"><button className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-white/55"><LayoutDashboard size={18}/>Dashboard</button><button className="flex w-full items-center gap-3 rounded-xl bg-white/10 px-3 py-2.5 text-sm font-medium"><Truck size={18}/>Pranchas<span className="ml-auto h-2 w-2 rounded-full bg-[#d6f269]"/></button></nav><div className="mt-auto"><AccountMenu user={user}/></div></aside></>}
function MobileHeader({open}:{open:()=>void}){return <div className="flex h-16 items-center justify-between border-b bg-white px-5 lg:hidden"><button onClick={open}><Menu/></button><span className="font-semibold">Plataforma Logística</span><Bell size={20}/></div>}
function Header({search,setSearch,filter,setFilter,onNew,onEquipment,onMaintenance}:{search:string;setSearch:(v:string)=>void;filter:string;setFilter:(v:Status|"Todos")=>void;onNew:()=>void;onEquipment:()=>void;onMaintenance:()=>void}){return <><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mb-2 text-xs font-semibold uppercase tracking-[.15em] text-[#688071]">Operação de transporte</div><h1 className="text-2xl font-semibold tracking-[-.03em] sm:text-3xl">Gestão de Pranchas</h1><p className="mt-1.5 text-sm text-[#6a776f]">Solicitação, deslocamento e manutenção em uma única visão.</p></div><div className="flex flex-wrap gap-2"><button onClick={onEquipment} className="flex h-11 items-center gap-2 rounded-xl border border-[#d9e0db] bg-white px-4 text-sm font-semibold"><Tractor size={17}/>Equipamentos</button><button onClick={onMaintenance} className="flex h-11 items-center gap-2 rounded-xl border border-[#d9e0db] bg-white px-4 text-sm font-semibold"><Wrench size={17}/>Manutenção</button><button onClick={onNew} className="flex h-11 items-center gap-2 rounded-xl bg-[#174e37] px-4 text-sm font-semibold text-white"><Plus size={18}/>Novo Frete</button></div></div><div className="panel mt-6 flex flex-col gap-3 p-3 md:flex-row md:items-center"><div className="flex items-center gap-2 border-b px-2 pb-3 text-sm font-medium md:border-b-0 md:border-r md:pb-0 md:pr-5"><CalendarDays size={17}/><span>01 ago, 2026</span></div><label className="flex min-w-0 flex-1 items-center gap-2 px-2"><Search size={17} className="text-[#7d8982]"/><input value={search} onChange={e=>setSearch(e.target.value)} className="w-full bg-transparent py-1 text-sm outline-none" placeholder="Pesquisar equipamento, código, frota, motorista ou rota..."/></label><div className="relative"><Filter className="absolute left-3 top-2.5" size={16}/><select value={filter} onChange={e=>setFilter(e.target.value as Status|"Todos")} className="h-9 appearance-none rounded-lg border bg-white pl-9 pr-8 text-sm"><option>Todos</option>{statuses.map(s=><option key={s}>{s}</option>)}</select><ChevronDown className="absolute right-2 top-3" size={14}/></div></div></>}

function Indicators({fretes,manutencoes}:{fretes:Frete[];manutencoes:Manutencao[]}){const current=operationKey();const items=[{label:"Pendentes",value:fretes.filter(f=>f.status==="Pendente").length,icon:Clock3,bg:"bg-amber-50",c:"text-amber-600"},{label:"Em Frete",value:fretes.filter(f=>f.status==="Em Frete").length,icon:Route,bg:"bg-blue-50",c:"text-blue-600"},{label:"Concluídos",value:fretes.filter(f=>f.status==="Concluído"&&f.operacao===current).length,icon:CheckCircle2,bg:"bg-emerald-50",c:"text-emerald-600"},{label:"Em Manutenção",value:manutencoes.filter(m=>m.status==="Em manutenção").length,icon:Wrench,bg:"bg-orange-50",c:"text-orange-600"}];return <div className="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-4">{items.map(x=><div className="panel flex items-center gap-3 p-4 sm:p-5" key={x.label}><div className={`grid h-10 w-10 place-items-center rounded-xl ${x.bg} ${x.c}`}><x.icon size={19}/></div><div><p className="text-xs text-[#758078]">{x.label}</p><p className="text-2xl font-semibold">{String(x.value).padStart(2,"0")}</p></div></div>)}</div>}
function Kanban({fretes,frotas,manutencoes,onFrete,onEdit,onCancel,onFinishMaintenance}:{fretes:Frete[];frotas:Frota[];manutencoes:Manutencao[];onFrete:(f:Frete)=>void;onEdit:(f:Frete)=>void;onCancel:(f:Frete)=>void;onFinishMaintenance:(m:Manutencao)=>void}){const [currentOperation,setCurrentOperation]=useState(operationKey());useEffect(()=>{const id=window.setInterval(()=>setCurrentOperation(operationKey()),60000);return()=>window.clearInterval(id)},[]);const active=fretes.filter(f=>f.status!=="Concluído"||f.operacao===currentOperation);return <section><div className="mb-5 flex flex-col justify-between gap-2 sm:flex-row sm:items-end"><div><h2 className="font-semibold">Operação atual</h2><p className="mt-1 text-xs text-[#7a867f]">07:00 às 06:59 do dia seguinte · Pendências e fretes permanecem ativos</p></div><span className="w-fit rounded-lg border border-[#e5e8e6] bg-white px-3 py-1.5 text-xs font-medium text-[#59625d]">{operationLabel(currentOperation)}</span></div><div className="grid items-start gap-5 md:grid-cols-2 2xl:grid-cols-4"><FreteColumn status="Pendente" fretes={active.filter(f=>f.status==="Pendente")} frotas={frotas} onClick={onFrete} onEdit={onEdit} onCancel={onCancel}/><FreteColumn status="Em Frete" fretes={active.filter(f=>f.status==="Em Frete")} frotas={frotas} onClick={onFrete} onEdit={onEdit} onCancel={onCancel}/><FreteColumn status="Concluído" fretes={active.filter(f=>f.status==="Concluído")} frotas={frotas} onClick={onFrete} onEdit={onEdit} onCancel={onCancel}/><MaintenanceColumn items={manutencoes.filter(m=>m.status==="Em manutenção")} finish={onFinishMaintenance}/></div></section>}
function ColumnShell({title,count,dot,children}:{title:string;count:number;dot:string;children:React.ReactNode}){return <div className="min-w-0 self-start"><div className="mb-4 flex items-center gap-2 border-b border-[#ecefed] px-1 pb-3"><span className={`h-2 w-2 rounded-full ${dot}`}/><h3 className="text-[13px] font-medium text-[#343a36]">{title}</h3><span className="text-xs tabular-nums text-[#929a95]">({count})</span></div><div className="space-y-3">{children}</div></div>}
function FreteColumn({status,fretes,frotas,onClick,onEdit,onCancel}:{status:Status;fretes:Frete[];frotas:Frota[];onClick:(f:Frete)=>void;onEdit:(f:Frete)=>void;onCancel:(f:Frete)=>void}){const dot=status==="Pendente"?"bg-amber-400":status==="Em Frete"?"bg-blue-500":"bg-emerald-500",line=status==="Pendente"?"before:bg-amber-400":status==="Em Frete"?"before:bg-blue-500":"before:bg-emerald-500";return <ColumnShell title={status} count={fretes.length} dot={dot}>{fretes.map(f=>{const fleet=frotas.find(x=>x.numero===f.frota)||getFrotaConfig(f.frota);return <button key={f.id} onClick={()=>onClick(f)} className={`group relative w-full overflow-hidden rounded-xl border border-[#e9ecea] bg-white p-4 text-left shadow-[0_1px_2px_rgba(18,24,21,.025)] before:absolute before:inset-y-0 before:left-0 before:w-[3px] ${line} transition-all duration-200 hover:-translate-y-0.5 hover:border-[#dce1de] hover:shadow-[0_8px_22px_rgba(18,24,21,.06)]`}><div className="flex min-w-0 items-center gap-2 text-[13px] font-medium text-[#262b28]"><MapPin size={15} className="shrink-0 text-[#727b76]"/><span className="truncate">{f.origem} <span className="text-[#a0a7a3]">→</span> {f.destino}</span></div><div className="mt-3.5 space-y-2.5 text-xs text-[#68716c]">{f.equipamentoTipo&&<span className="flex items-center gap-2 text-[12px] font-medium text-[#414844]"><Tractor size={14}/>{f.equipamentoTipo} {f.equipamentoCodigo}</span>}<span className="flex items-center gap-2"><Clock3 size={14}/>{f.horario}</span>{f.status!=="Pendente"&&<><span className="flex items-center gap-2"><Truck size={14}/>{f.frota}{fleet&&<><span className="text-[#b0b6b2]">•</span><Route size={14}/> {fleet.prancha}</>}</span><span className="flex items-center gap-2 truncate"><UserRound size={14} className="shrink-0"/><span className="truncate">{f.motorista}</span></span></>}{fleet?.possuiPreOs&&<span className="flex items-center gap-2 text-[10px] font-medium text-amber-700">⚠ Pré-OS: {fleet.numeroPreOs}</span>}<span className={`inline-flex w-fit rounded-md px-1.5 py-1 text-[9px] font-medium ${priorityStyle[f.prioridade]}`}>{f.prioridade==="Alta"?"● Alta":f.prioridade==="Média"?"● Média":"● Baixa"}</span></div>{f.status!=="Concluído"&&<div className="mt-3 flex items-center gap-2 border-t border-[#edf0ee] pt-3"><span role="button" tabIndex={0} onClick={e=>{e.stopPropagation();onEdit(f)}} className="inline-flex flex-1 items-center justify-center gap-1.5 rounded-lg border border-[#dfe4e1] px-2 py-1.5 text-[10px] font-medium text-[#59645d] transition-colors hover:bg-[#f4f6f4]"><Pencil size={11}/>Editar</span><span role="button" tabIndex={0} onClick={e=>{e.stopPropagation();onCancel(f)}} className="inline-flex flex-1 items-center justify-center gap-1.5 rounded-lg border border-red-100 px-2 py-1.5 text-[10px] font-medium text-red-600 transition-colors hover:bg-red-50"><X size={11}/>Cancelar</span></div>}</button>})}{!fretes.length&&<div className="rounded-xl border border-dashed border-[#e5e8e6] p-5 text-center text-xs text-[#969e99]">Nenhum registro</div>}</ColumnShell>}
function MaintenanceColumn({items,finish}:{items:Manutencao[];finish:(m:Manutencao)=>void}){return <ColumnShell title="Manutenção" count={items.length} dot="bg-orange-500">{items.map(m=><div key={m.id} className="rounded-xl border border-orange-100 bg-white p-4 shadow-sm"><p className="flex items-center gap-2 font-semibold"><Truck size={15}/>Frota {m.frota}</p><div className="mt-3 space-y-2 text-xs text-[#68756d]"><p className="flex items-center gap-2"><FileText size={14}/>OS: {m.numeroOs}</p><p className="flex items-center gap-2"><MapPin size={14}/>Local: {m.localizacao}</p>{m.freteId&&<p className="rounded-lg bg-orange-50 p-2 text-orange-800">Frete interrompido: {m.freteId}</p>}<p className="flex items-start gap-2"><Wrench size={14} className="mt-0.5 shrink-0"/><span><b className="font-medium">Serviço:</b><br/>{m.servico}</span></p><p className="flex items-start gap-2"><Clock3 size={14} className="mt-0.5 shrink-0"/><span><b className="font-medium">Previsão:</b><br/>{m.previsao?`${m.previsaoData?.slice(0,5)} às ${m.previsaoHora}`:"Sem previsão"}</span></p></div><button onClick={()=>finish(m)} className="mt-4 w-full rounded-lg bg-[#174e37] py-2 text-xs font-semibold text-white">Finalizar Manutenção</button></div>)}</ColumnShell>}

const fc=createColumnHelper<Frete>(),mc=createColumnHelper<Manutencao>();
function HistoryTabs({tab,setTab,fretes,onFrete,manutencoes,filter,setFilter}:{tab:"fretes"|"manutencao";setTab:(v:"fretes"|"manutencao")=>void;fretes:Frete[];onFrete:(f:Frete)=>void;manutencoes:Manutencao[];filter:string;setFilter:(v:Status|"Todos")=>void}){return <section className="panel overflow-hidden"><div className="flex border-b px-5 pt-4"><button onClick={()=>setTab("fretes")} className={`border-b-2 px-3 py-3 text-sm font-semibold ${tab==="fretes"?"border-[#174e37] text-[#174e37]":"border-transparent text-[#78847d]"}`}>Histórico de Fretes</button><button onClick={()=>setTab("manutencao")} className={`border-b-2 px-3 py-3 text-sm font-semibold ${tab==="manutencao"?"border-[#174e37] text-[#174e37]":"border-transparent text-[#78847d]"}`}>Histórico de Manutenção</button></div>{tab==="fretes"?<FreightHistoryTable fretes={fretes} filter={filter} setFilter={setFilter} onFrete={onFrete}/>:<MaintenanceHistoryTable items={manutencoes}/>}</section>}
function FreightHistory({fretes,filter,setFilter,onFrete}:{fretes:Frete[];filter:string;setFilter:(v:Status|"Todos")=>void;onFrete:(f:Frete)=>void}){const [expanded,setExpanded]=useState(false);const columns=[fc.display({id:"dh",header:"Data/Hora",cell:i=><div className="whitespace-nowrap"><p className="text-sm font-medium text-[#343b37]">{i.row.original.data.slice(0,5)}</p><p className="mt-1 text-[11px] text-[#8a938e]">{i.row.original.horario}</p></div>}),fc.accessor("status",{header:"Status",cell:i=><span className={`inline-flex items-center gap-1.5 whitespace-nowrap rounded-full border px-2 py-1 text-[10px] font-medium ${statusStyle[i.getValue()]}`}><i className="h-1.5 w-1.5 rounded-full bg-current opacity-75"/>{i.getValue()}</span>}),fc.display({id:"equipamento",header:"Equipamento",cell:i=>i.row.original.equipamentoTipo?<div><p className="whitespace-nowrap text-sm font-medium text-[#303733]">{i.row.original.equipamentoTipo}</p><p className="mt-1 text-[11px] text-[#89928d]">{i.row.original.equipamentoCodigo}</p></div>:<span className="text-[#a0a7a3]">—</span>}),fc.accessor("frota",{header:"Frota",cell:i=><span className="flex items-center gap-1.5 whitespace-nowrap text-sm"><Truck size={14} className="text-[#7d8781]"/>{i.getValue()||"—"}</span>}),fc.accessor("motorista",{header:"Motorista",cell:i=><span title={i.getValue()||"—"} className="block overflow-hidden text-ellipsis whitespace-nowrap text-sm text-[#505954]">{i.getValue()||"—"}</span>}),fc.accessor("origem",{header:"Origem",cell:i=><span className="block break-words text-sm font-medium leading-5 text-[#3b433e]">{i.getValue()}</span>}),fc.accessor("destino",{header:"Destino",cell:i=><span className="block break-words text-sm leading-5 text-[#505954]">{i.getValue()}</span>}),fc.accessor("setor",{header:"Setor",cell:i=><span title={i.getValue()} className="block overflow-hidden text-ellipsis whitespace-nowrap text-sm text-[#505954]">{i.getValue()}</span>}),fc.accessor("solicitante",{header:"Solicitante",cell:i=><span title={i.getValue()} className="block overflow-hidden text-ellipsis whitespace-nowrap text-sm text-[#505954]">{i.getValue()}</span>}),fc.accessor("responsavel",{header:"Resp. Logística",cell:i=><span title={i.getValue()} className="block overflow-hidden text-ellipsis whitespace-nowrap text-sm text-[#505954]">{i.getValue()}</span>})];const table=useReactTable({data:fretes,columns,getCoreRowModel:getCoreRowModel()});const chip=(s:string)=>s==="Pendente"?"border-amber-200 text-amber-700":s==="Em Frete"?"border-blue-200 text-blue-700":s==="Concluído"?"border-emerald-200 text-emerald-700":"border-[#dfe4e1] text-[#66716a]",active=(s:string)=>s==="Pendente"?"border-amber-600 bg-amber-600":s==="Em Frete"?"border-blue-600 bg-blue-600":s==="Concluído"?"border-emerald-600 bg-emerald-600":"border-[#174e37] bg-[#174e37]";return <div className={expanded?"fixed inset-3 z-50 overflow-auto rounded-2xl border border-[#e3e7e4] bg-white shadow-2xl":""}><div className="flex flex-wrap items-center gap-2 border-b border-[#edf0ee] bg-white px-5 py-3">{["Todos",...statuses].map(s=><button key={s} onClick={()=>setFilter(s as Status|"Todos")} className={`rounded-full border px-3 py-1.5 text-[11px] font-medium transition-all duration-200 ${filter===s?`${active(s)} text-white shadow-sm`:`bg-white ${chip(s)} hover:bg-[#fafbfa]`}`}>{s!=="Todos"&&<i className="mr-1.5 inline-block h-1.5 w-1.5 rounded-full bg-current"/>}{s==="Cancelado"?"Cancelados":s}</button>)}<button onClick={()=>setExpanded(v=>!v)} className="ml-auto rounded-lg border border-[#dfe4e1] bg-white px-3 py-1.5 text-[11px] font-medium text-[#566159] transition-colors hover:bg-[#f6f8f6]">{expanded?"⤢ Recolher":"⛶ Expandir"}</button></div><DataTable table={table} onRowClick={row=>onFrete(row.original as Frete)} modern expanded={expanded}/></div>}
function duration(m:Manutencao){if(!m.saidaData||!m.saidaHora)return"Em andamento";const parse=(d:string,t:string)=>{const [day,mo,y]=d.split("/").map(Number),[h,min]=t.split(":").map(Number);return new Date(y,mo-1,day,h,min).getTime()};const mins=Math.max(0,Math.floor((parse(m.saidaData,m.saidaHora)-parse(m.entradaData,m.entradaHora))/60000));return `${Math.floor(mins/60)}h ${mins%60}min`}
function MaintenanceHistory({items}:{items:Manutencao[]}){const [f,setF]=useState<"Todas"|"Em manutenção"|"Finalizadas">("Todas");const data=items.filter(m=>f==="Todas"||(f==="Em manutenção"?m.status==="Em manutenção":m.status==="Finalizada"));const columns=[mc.accessor("frota",{header:"Frota"}),mc.accessor("numeroOs",{header:"OS"}),mc.accessor("localizacao",{header:"Local"}),mc.accessor("freteId",{header:"Frete interrompido",cell:i=>i.getValue()||"—"}),mc.accessor("entradaData",{header:"Data entrada"}),mc.accessor("entradaHora",{header:"Hora entrada"}),mc.accessor("saidaData",{header:"Data saída",cell:i=>i.getValue()||"—"}),mc.accessor("saidaHora",{header:"Hora saída",cell:i=>i.getValue()||"—"}),mc.display({id:"tempo",header:"Tempo",cell:i=>duration(i.row.original)}),mc.accessor("tipo",{header:"Tipo"}),mc.accessor("servico",{header:"Serviço realizado"}),mc.accessor("responsavel",{header:"Responsável"}),mc.accessor("observacoes",{header:"Observações"})];const table=useReactTable({data,columns,getCoreRowModel:getCoreRowModel()});return <><div className="flex gap-1 p-4">{(["Todas","Em manutenção","Finalizadas"] as const).map(x=><button onClick={()=>setF(x)} key={x} className={`rounded-lg px-3 py-1.5 text-xs ${f===x?"bg-[#174e37] text-white":"bg-[#f4f6f4]"}`}>{x}</button>)}</div><DataTable table={table}/></>}
function DataTable({table,onRowClick,modern=false,expanded=false}:{table:ReturnType<typeof useReactTable<any>>;onRowClick?:(row:any)=>void;modern?:boolean;expanded?:boolean}){const widths:Record<string,string>={dh:"7%",status:"9%",equipamento:"16%",frota:"6%",motorista:"13%",origem:"10%",destino:"10%",setor:"8%",solicitante:"11%",responsavel:"10%"};return <div className={modern?"overflow-hidden bg-[#f8faf8] p-2 sm:p-3":"overflow-x-auto"}><table className={`w-full text-left text-sm ${modern?(expanded?"min-w-[1400px] table-fixed":"table-fixed"):"min-w-[1100px]"}`}><thead className={modern?"bg-white text-[9px] uppercase tracking-[.08em] text-[#89928d]":"bg-[#fafbfa] text-[10px] uppercase tracking-[.06em] text-[#7f8883]"}>{table.getHeaderGroups().map(g=><tr key={g.id}>{g.headers.map(h=><th className={modern?`${!expanded&&["setor","solicitante","responsavel"].includes(h.column.id)?"hidden":""} px-3 py-2.5 font-medium whitespace-nowrap`:"px-5 py-4"} style={modern?{width:widths[h.column.id]}:undefined} key={h.id}>{flexRender(h.column.columnDef.header,h.getContext())}</th>)}</tr>)}</thead><tbody className={modern?"before:block before:h-2":""}>{table.getRowModel().rows.map(r=><tr onClick={()=>onRowClick?.(r)} className={modern?"group border-b-4 border-[#f8faf8] bg-white shadow-[0_1px_2px_rgba(17,24,20,.025)] transition-all duration-200 hover:-translate-y-px hover:bg-[#fbfcfb] hover:shadow-[0_5px_14px_rgba(17,24,20,.055)] cursor-pointer":"border-t border-[#eef0ef] transition-colors duration-200 hover:bg-[#fafbfa]"} key={r.id}>{r.getVisibleCells().map(c=><td className={modern?`${!expanded&&["setor","solicitante","responsavel"].includes(c.column.id)?"hidden":""} px-3 py-5 align-middle first:rounded-l-lg last:rounded-r-lg`:"px-5 py-5 align-middle"} style={modern?{width:widths[c.column.id]}:undefined} key={c.id}>{flexRender(c.column.columnDef.cell,c.getContext())}</td>)}</tr>)}</tbody></table></div>}

function Whatsapp({flow,flowRef,generate,copy,download,send,copied}:{flow:string;flowRef:React.RefObject<HTMLDivElement|null>;generate:()=>void;copy:()=>void;download:()=>void;send:()=>void;copied:boolean}){return <section className="panel p-5"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-emerald-50 text-emerald-700"><MessageCircle size={19}/></div><div><h2 className="font-semibold">Fluxo WhatsApp</h2><p className="text-xs text-[#7c8780]">Gerado automaticamente pelos cadastros</p></div></div><button onClick={generate} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-[#174e37] py-2.5 text-sm font-semibold text-white"><Send size={16}/>Gerar Programação</button>{flow&&<><div ref={flowRef} aria-readonly className="mt-4 max-h-[420px] overflow-y-auto whitespace-pre-wrap rounded-xl border bg-[#f8faf8] p-4 text-xs leading-5">{flow}</div><div className="mt-3 grid grid-cols-2 gap-2"><button onClick={copy} className="rounded-lg border py-2 text-xs font-semibold">{copied?<Check size={14} className="inline"/>:<Copy size={14} className="inline"/>} {copied?"Copiado":"Copiar Texto"}</button><button onClick={download} className="rounded-lg border py-2 text-xs font-semibold"><Download size={14} className="inline"/> Baixar como Imagem</button><button onClick={send} className="col-span-2 rounded-lg bg-[#21a461] py-2.5 text-xs font-semibold text-white">Compartilhar via WhatsApp</button></div></>}</section>}
function FleetStatus({frotas,onPreOs}:{frotas:Frota[];onPreOs:(f:Frota)=>void}){const [query,setQuery]=useState("");const colors={Disponível:"bg-emerald-500","Em Frete":"bg-blue-500",Manutenção:"bg-orange-500"};const filtered=frotas.filter(f=>`${f.numero} ${f.prancha} ${f.status} ${f.localDisponivel||""}`.toLowerCase().includes(query.toLowerCase()));return <section className="panel p-5"><div className="mb-4 flex items-center gap-2.5"><CircleGauge size={16} className="text-[#69726d]"/><div><h2 className="text-sm font-medium">Status das Pranchas</h2><p className="mt-0.5 text-[11px] text-[#8a938e]">Visão rápida das 7 frotas</p></div></div><label className="mb-3 flex items-center gap-2 rounded-lg border border-[#e6e9e7] bg-[#fafbfa] px-3 py-2"><Search size={14} className="text-[#8b948f]"/><input value={query} onChange={e=>setQuery(e.target.value)} className="w-full bg-transparent text-xs outline-none" placeholder="Pesquisar frota..."/></label><div className="divide-y divide-[#edf0ee]">{filtered.map(f=><div className="px-1 py-3 transition-colors duration-200 first:pt-2 last:pb-1 hover:bg-[#fafbfa]" key={f.numero}><div className="flex items-center gap-4 text-sm font-medium text-[#343a36]"><span className="flex items-center gap-1.5"><Truck size={14} className="text-[#747d78]"/>{f.numero}</span><span className="flex items-center gap-1.5 text-[#626c66]"><Route size={14} className="text-[#858e89]"/>{f.prancha}</span></div><div className="mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-[#68726c]"><span className="flex items-center gap-1.5"><i className={`h-2 w-2 rounded-full ${colors[f.status]}`}/>{f.status}</span>{f.status==="Disponível"&&f.localDisponivel&&<><span className="text-[#c4cac6]">•</span><span className="flex items-center gap-1"><MapPin size={12}/>{f.localDisponivel}</span></>}</div>{f.tipo&&<div className="mt-1.5 inline-flex items-center gap-1 rounded-md bg-[#f1f3f2] px-1.5 py-0.5 text-[10px] font-medium text-[#69726d]"><Wrench size={10}/>{f.tipo}</div>}<div className="mt-1.5 flex items-center justify-between gap-2">{f.possuiPreOs?<span className="text-[10px] font-medium text-amber-700">⚠ Pré-OS: {f.numeroPreOs}</span>:<span/>}<button onClick={()=>onPreOs(f)} className="text-[10px] font-medium text-[#59655e] hover:text-[#174e37]">{f.possuiPreOs?"Editar Pré-OS":"+ Pré-OS"}</button></div></div>)}{!filtered.length&&<p className="py-5 text-center text-xs text-[#929a95]">Nenhuma frota encontrada</p>}</div></section>}

function Modal({open,close,title,description,children,wide=false}:{open:boolean;close:()=>void;title:string;description:string;children:React.ReactNode;wide?:boolean}){return <Dialog.Root open={open} onOpenChange={v=>!v&&close()}><Dialog.Portal><Dialog.Overlay className="fixed inset-0 z-50 bg-[#101914]/40"/><Dialog.Content className={`fadein fixed left-1/2 top-1/2 z-50 max-h-[92vh] w-[calc(100%-2rem)] -translate-x-1/2 -translate-y-1/2 overflow-y-auto rounded-2xl bg-white shadow-2xl outline-none ${wide?"max-w-2xl":"max-w-md"}`}><div className="flex justify-between border-b p-5"><div><Dialog.Title className="font-semibold">{title}</Dialog.Title><Dialog.Description className="mt-1 text-xs text-[#78847d]">{description}</Dialog.Description></div><Dialog.Close><X size={18}/></Dialog.Close></div>{children}</Dialog.Content></Dialog.Portal></Dialog.Root>}
function Drawer({open,close,title,children}:{open:boolean;close:()=>void;title:string;children:React.ReactNode}){return <Dialog.Root open={open} onOpenChange={v=>!v&&close()}><Dialog.Portal><Dialog.Overlay className="fixed inset-0 z-50 bg-[#101914]/35"/><Dialog.Content className="fixed inset-y-0 right-0 z-50 w-full max-w-[510px] overflow-y-auto bg-white shadow-2xl outline-none"><div className="sticky top-0 z-10 flex justify-between border-b bg-white p-5"><Dialog.Title className="font-semibold">{title}</Dialog.Title><Dialog.Close><X size={18}/></Dialog.Close></div>{children}</Dialog.Content></Dialog.Portal></Dialog.Root>}
function FreteDrawer({frete,close,start,complete}:{frete:Frete|null;close:()=>void;start:()=>void;complete:()=>void}){if(!frete)return null;return <Drawer open close={close} title={`Frete ${frete.id}`}><div className="p-6"><div className="rounded-2xl bg-[#173d2e] p-5 text-white"><div className="flex justify-between"><b>{frete.status==="Pendente"?"Aguardando prancha":`Frota ${frete.frota}`}</b><span className="rounded-full bg-white/10 px-3 py-1 text-xs">{frete.status}</span></div><p className="mt-4 flex gap-2 text-sm"><MapPin size={16}/>{frete.origem} → {frete.destino}</p>{frete.equipamentoTipo&&<p className="mt-3 flex gap-2 text-sm"><Tractor size={16}/>{frete.equipamentoTipo} {frete.equipamentoCodigo}</p>}</div><div className="mt-6 grid grid-cols-2 gap-5">{[["Data/Hora",`${frete.data} ${frete.horario}`],["Setor",frete.setor],["Solicitante",frete.solicitante],["Resp. Logística",frete.responsavel],["Prioridade",frete.prioridade],["Motorista",frete.motorista||"Não definido"],["Início",frete.inicioDeslocamento||"—"],["Conclusão",frete.conclusao||"—"]].map(([a,b])=><div key={a}><p className="text-[11px] uppercase text-[#89948d]">{a}</p><p className="mt-1 text-sm font-medium">{b}</p></div>)}</div>{frete.status==="Cancelado"&&<div className="mt-6 rounded-xl border border-red-100 bg-red-50 p-4 text-sm text-red-800"><p className="font-semibold">Frete cancelado</p><p className="mt-2 text-xs"><b>Solicitado por:</b> {frete.cancelamentoSolicitadoPor}</p><p className="mt-1 text-xs"><b>Motivo:</b> {frete.motivoCancelamento}</p><p className="mt-1 text-xs"><b>Data/Hora:</b> {frete.canceladoEm}</p></div>}{frete.observacao&&<p className="mt-6 rounded-xl bg-[#f5f7f5] p-4 text-sm"><b className="mb-1 block text-xs">Observação</b>{frete.observacao}</p>}{frete.status==="Pendente"&&<button onClick={start} className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-blue-600 py-3 text-sm font-semibold text-white"><Play size={17}/>Iniciar Deslocamento</button>}{frete.status==="Em Frete"&&<button onClick={complete} className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-[#174e37] py-3 text-sm font-semibold text-white"><CheckCircle2 size={17}/>Finalizar Frete</button>}</div></Drawer>}
function NewFrete({open,close,equipamentos:_,add}:{open:boolean;close:()=>void;equipamentos:Equipamento[];add:(f:Frete)=>void}){const {register,handleSubmit,reset,formState:{errors}}=useForm<AgendamentoInput>({resolver:zodResolver(agendamentoSchema),defaultValues:{prioridade:"Média",observacao:""}});const submit=(d:AgendamentoInput)=>{add({...d,id:`FR-${1060+Math.floor(Math.random()*90)}`,operacao:operationKey(),data:new Date(d.data+"T12:00").toLocaleDateString("pt-BR"),status:"Pendente"});reset();close()};return <Drawer open={open} close={close} title="Novo Frete"><form onSubmit={handleSubmit(submit)} className="p-6"><div className="grid gap-4 sm:grid-cols-2"><label className="sm:col-span-2"><span className="label">Equipamento</span><input className="field" placeholder="Ex.: Pá Carregadeira 41002" {...register("equipamentoTipo")}/><p className="mt-1 text-xs text-[#7c8880]">Digite o nome do equipamento seguido da frota, como Colhedora 61065.</p></label>{([['data','Data','date'],['horario','Horário','time'],['setor','Setor Solicitante'],['solicitante','Solicitante'],['responsavel','Responsável da Logística'],['origem','Origem'],['destino','Destino']] as const).map(([n,l,t],i)=><label className={i>1?"sm:col-span-2":""} key={n}><span className="label">{l}</span><input type={t||"text"} className="field" {...register(n)}/>{errors[n]&&<small className="text-red-600">{errors[n]?.message}</small>}</label>)}<label><span className="label">Prioridade</span><select className="field" {...register("prioridade")}><option>Baixa</option><option>Média</option><option>Alta</option></select></label><div/><label className="sm:col-span-2"><span className="label">Observação</span><textarea rows={4} className="field" placeholder="Opcional" {...register("observacao")}/></label></div><button className="mt-6 w-full rounded-xl bg-[#174e37] py-3 text-sm font-semibold text-white">Solicitar Frete</button><p className="mt-3 text-center text-xs text-[#7c8880]">O frete será criado como Pendente, sem frota e motorista.</p></form></Drawer>}
function EquipmentModal({open,close,equipamentos,add}:{open:boolean;close:()=>void;equipamentos:Equipamento[];add:(e:Equipamento)=>void}){const {register,handleSubmit,reset,formState:{errors}}=useForm<EquipamentoInput>({resolver:zodResolver(equipamentoSchema)});const [custom,setCustom]=useState(false);const types=["Pá Carregadeira","Colhedora","Trator","Escavadeira","Motoniveladora","Transbordo","Plantadora","Pulverizador","Caminhão","Implemento","Outro"];const save=(d:EquipamentoInput)=>{add({...d,id:`EQ-${Date.now()}`});reset()};return <Modal open={open} close={close} title="Cadastro de Equipamentos" description="Catálogo pesquisável utilizado nos fretes" wide><div className="p-5"><form onSubmit={handleSubmit(save)} className="grid gap-4 sm:grid-cols-2"><label><span className="label">Código do equipamento</span><input className="field" placeholder="Ex.: 41002" {...register("codigo")}/>{errors.codigo&&<small className="text-red-600">{errors.codigo.message}</small>}</label><label><span className="label">Tipo do equipamento</span>{custom?<input className="field" placeholder="Novo tipo" {...register("tipo")}/>:<select className="field" {...register("tipo")} onChange={e=>{if(e.target.value==="Outro")setCustom(true)}}><option value="">Selecione</option>{types.map(t=><option key={t}>{t}</option>)}</select>}</label><label className="sm:col-span-2"><span className="label">Descrição (opcional)</span><input className="field" {...register("descricao")}/></label><button className="rounded-xl bg-[#174e37] py-2.5 text-sm font-semibold text-white sm:col-span-2"><Plus size={16} className="inline"/> Adicionar Equipamento</button></form><div className="mt-6 max-h-64 overflow-y-auto rounded-xl border"><table className="w-full text-left text-sm"><thead className="sticky top-0 bg-[#f7f9f7] text-xs text-[#718078]"><tr><th className="p-3">Código</th><th className="p-3">Tipo</th><th className="p-3">Descrição</th></tr></thead><tbody>{equipamentos.map(e=><tr className="border-t" key={e.id}><td className="p-3 font-semibold">{e.codigo}</td><td className="p-3">{e.tipo}</td><td className="p-3 text-[#718078]">{e.descricao||"—"}</td></tr>)}</tbody></table></div></div></Modal>}
function FleetCombobox({frotas,value,onChange}:{frotas:Frota[];value?:string;onChange:(v:string)=>void}){const [query,setQuery]=useState(""),[open,setOpen]=useState(false);const selected=frotas.find(f=>f.numero===value);const options=frotas.filter(f=>`${f.numero} ${f.prancha} ${f.tipo||""}`.toLowerCase().includes(query.toLowerCase()));return <div><div className="relative"><Search size={15} className="pointer-events-none absolute left-3 top-3.5 text-[#8a938e]"/><input className="field pl-9" value={open?query:selected?`Frota ${selected.numero} · Prancha ${selected.prancha}`:""} onFocus={()=>{setOpen(true);setQuery("")}} onChange={e=>{setQuery(e.target.value);setOpen(true)}} placeholder="Pesquisar frota ou prancha..."/>{open&&<div className="absolute z-30 mt-2 max-h-64 w-full overflow-y-auto rounded-xl border border-[#e2e6e3] bg-white p-1.5 shadow-xl">{options.map(f=><button type="button" disabled={f.status!=="Disponível"} onClick={()=>{onChange(f.numero);setOpen(false);setQuery("")}} className="flex w-full items-start justify-between rounded-lg px-3 py-3 text-left hover:bg-[#f7f9f7] disabled:cursor-not-allowed disabled:opacity-45" key={f.numero}><div><p className="flex items-center gap-2 text-sm font-medium"><Truck size={15}/>Frota {f.numero}</p><p className="mt-1 pl-[23px] text-xs text-[#727b76]">Prancha {f.prancha}</p>{f.tipo&&<p className="mt-1 flex items-center gap-2 pl-[23px] text-xs text-[#727b76]"><Wrench size={13}/>{f.tipo}</p>}</div>{f.status!=="Disponível"&&<span className="text-[10px] text-[#89918c]">{f.status}</span>}</button>)}{!options.length&&<p className="p-4 text-center text-xs text-[#8b948f]">Nenhuma frota encontrada</p>}</div>}</div>{selected&&<div className="mt-3 rounded-xl border border-[#e8ebe9] bg-[#fafbfa] p-4"><p className="flex items-center gap-2 text-sm font-medium"><Truck size={15}/>Frota {selected.numero}</p><p className="mt-2 pl-[23px] text-xs text-[#68716c]">Prancha {selected.prancha}</p>{selected.tipo&&<p className="mt-2 flex items-center gap-2 pl-[23px] text-xs text-[#68716c]"><Wrench size={14}/>{selected.tipo}</p>}</div>}</div>}
function StartModal({frete,close,frotas,confirm}:{frete:Frete|null;close:()=>void;frotas:Frota[];confirm:(f:Frete,d:DeslocamentoInput)=>void}){const {register,handleSubmit,reset,watch,setValue}=useForm<DeslocamentoInput>({resolver:zodResolver(deslocamentoSchema)});const selected=watch("frota");if(!frete)return null;return <Modal open close={close} title="Iniciar Deslocamento" description="Vincule a frota e o motorista ao frete"><form onSubmit={handleSubmit(d=>{confirm(frete,d);reset()})} className="space-y-4 p-5"><label><span className="label">Frota</span><FleetCombobox frotas={frotas} value={selected} onChange={v=>setValue("frota",v,{shouldValidate:true})}/><input type="hidden" {...register("frota")}/></label><label><span className="label">Motorista</span><input className="field" placeholder="Nome do motorista" {...register("motorista")}/></label><div className="flex gap-3 pt-3"><button type="button" onClick={close} className="flex-1 rounded-xl border py-3 text-sm font-semibold">Cancelar</button><button className="flex-1 rounded-xl bg-blue-600 py-3 text-sm font-semibold text-white">Confirmar</button></div></form></Modal>}
function MaintenanceModal({open,close,frotas,save}:{open:boolean;close:()=>void;frotas:Frota[];save:(d:ManutencaoInput)=>void}){const n=nowParts();const {register,handleSubmit,watch,setValue,formState:{errors}}=useForm<ManutencaoInput>({resolver:zodResolver(manutencaoSchema),defaultValues:{entradaData:n.iso,entradaHora:n.time,tipo:"Preventiva",previsao:"nao",observacoes:""}});const previsao=watch("previsao"),selected=watch("frota");return <Modal open={open} close={close} title="Colocar em Manutenção" description="A frota ficará bloqueada até a finalização" wide><form onSubmit={handleSubmit(save)} className="grid gap-4 p-5 sm:grid-cols-2"><label className="sm:col-span-2"><span className="label">Frota</span><FleetCombobox frotas={frotas} value={selected} onChange={v=>setValue("frota",v,{shouldValidate:true})}/><input type="hidden" {...register("frota")}/></label><label><span className="label">Data de entrada</span><input type="date" className="field" {...register("entradaData")}/></label><label><span className="label">Hora de entrada</span><input type="time" className="field" {...register("entradaHora")}/></label><label><span className="label">Tipo</span><select className="field" {...register("tipo")}><option>Preventiva</option><option>Corretiva</option></select></label><label className="sm:col-span-2"><span className="label">Serviço a ser realizado</span><input className="field" {...register("servico")}/></label><label className="sm:col-span-2"><span className="label">Observações</span><textarea className="field" rows={3} {...register("observacoes")}/></label><fieldset className="sm:col-span-2"><legend className="label">Possui previsão de retorno?</legend><div className="flex gap-5 text-sm"><label><input type="radio" value="sim" {...register("previsao")}/> Sim</label><label><input type="radio" value="nao" {...register("previsao")}/> Não</label></div></fieldset>{previsao==="sim"&&<><label><span className="label">Data prevista</span><input type="date" className="field" {...register("previsaoData")}/></label><label><span className="label">Hora prevista</span><input type="time" className="field" {...register("previsaoHora")}/></label></>}{errors.previsaoData&&<p className="text-xs text-red-600 sm:col-span-2">{errors.previsaoData.message}</p>}<div className="flex gap-3 pt-3 sm:col-span-2"><button type="button" onClick={close} className="flex-1 rounded-xl border py-3 text-sm font-semibold">Cancelar</button><button className="flex-1 rounded-xl bg-[#174e37] py-3 text-sm font-semibold text-white">Salvar</button></div></form></Modal>}
